The rule keeps the default’s balanced reuse for homogeneous cases, but when duty lengths differ it scores each available robot by the marginal increase in normalized variance of both duty counts and duty hours, so mixed 6/8/10/12 h types stay balanced in hours rather than just counts. For new robots, it estimates how many duty hours a type can actually supply over the remaining horizon (accounting for travel, charging, maintenance cycles and budget), filters choices that leave an un-coverable remainder, and prefers the type that maximises coverage per robot with longer duties as a tie-breaker to save tools.

```python
def rule(ctx):
    def get_type(k):
        if k is None or k < 0 or k >= len(ctx.types):
            return None
        return ctx.types[k]

    def gcd_small(a, b):
        if a < b:
            a, b = b, a
        for i in range(int(b), 0, -1):
            if a % i == 0 and b % i == 0:
                return i
        return 1

    # Average duty length for normalising the balance score.
    total_wt = 0.0
    n_wt = 0
    for typ in ctx.types:
        if typ is not None:
            total_wt += float(typ["work_time"])
            n_wt += 1
    avg_wt = total_wt / n_wt if n_wt > 0 else 10.0
    if avg_wt <= 0:
        avg_wt = 10.0

    # Reuse order: balance count and hours, then prefer fresher (higher budget) robots.
    def reuse_key(r):
        typ = get_type(r.type)
        wt = float(typ["work_time"]) if typ is not None else 10.0
        score = (r.count + 0.5) + (r.hours * wt + 0.5 * wt * wt) / (avg_wt * avg_wt)
        return (score, -r.budget, r.idx)

    reuses = sorted(ctx.available, key=reuse_key)

    # Possible duty lengths for checking whether the remaining horizon can be covered.
    duties = set()
    for r in ctx.robots:
        typ = get_type(r.type)
        if typ is not None:
            duties.add(int(round(float(typ["work_time"]))))
    for k, typ in enumerate(ctx.types):
        if typ is not None and ctx.left[k] > 0:
            duties.add(int(round(float(typ["work_time"]))))

    rem = float(ctx.remaining)
    rem_int = int(round(rem))
    need_cover = (len(ctx.available) == 0)

    def can_cover(amount, dset):
        if amount < 0:
            return False
        if amount == 0:
            return True
        if not dset:
            return False
        g = 0
        for d in dset:
            if d > 0:
                g = d if g == 0 else gcd_small(g, d)
        if g == 0 or amount % g != 0:
            return False
        # With duty lengths <= 12, all sufficiently large multiples of gcd are representable.
        if amount >= 200:
            return True
        can = [False] * (amount + 1)
        can[0] = True
        for d in dset:
            if d <= amount:
                for s in range(d, amount + 1):
                    if can[s - d]:
                        can[s] = True
        return can[amount]

    candidates = []
    for k, typ in enumerate(ctx.types):
        if typ is None or ctx.left[k] <= 0:
            continue

        duty = float(typ["work_time"])
        out = float(typ["out_travel_time"])
        ret = float(typ["return_travel_time"])
        single = float(typ["single_work_time"])
        cmax = float(typ["continue_max_work"])
        charge = float(typ["charge_time"])
        maint = float(typ["maintenance_time"])
        if single <= 0:
            single = 1.0

        dpc = max(1, int(cmax / single + 1e-9))
        cycle = out + duty + ret + charge
        if cycle <= 0:
            cycle = duty + 1.0

        # Estimate duty hours this new robot can supply before T.
        if rem < duty:
            coverage = 0.0
        else:
            first_cycle_duration = (dpc - 1) * cycle + duty
            if rem < first_cycle_duration:
                n = 1 + int((rem - duty) // cycle)
                n = min(dpc, n)
                coverage = n * duty
            else:
                interval = (dpc - 1) * cycle + duty + ret + maint + out
                if interval <= 0:
                    interval = first_cycle_duration + maint + 1.0
                full_cycles = 1 + int((rem - first_cycle_duration) // interval)
                total_duties = full_cycles * dpc
                next_start = full_cycles * interval
                if rem >= next_start + duty:
                    n_extra = 1 + int((rem - next_start - duty) // cycle)
                    n_extra = min(dpc, n_extra)
                    total_duties += n_extra
                coverage = total_duties * duty
        if coverage > rem:
            coverage = rem

        duty_int = int(round(duty))
        if need_cover and duty_int <= rem_int:
            coverable = can_cover(rem_int - duty_int, duties)
        else:
            coverable = duty_int <= rem_int

        candidates.append({
            "k": k,
            "duty": duty,
            "coverage": coverage,
            "maint": maint,
            "cycle": cycle,
            "coverable": coverable,
            "fits": duty_int <= rem_int
        })

    def cand_key(c):
        return (
            0 if c["coverable"] else 1,
            0 if c["fits"] else 1,
            -c["coverage"],
            -c["duty"],
            c["maint"],
            c["cycle"],
            c["k"]
        )

    candidates.sort(key=cand_key)
    new_actions = [("new", c["k"]) for c in candidates]

    if not new_actions:
        new_actions = [("new", ctx.gene_type)]
    else:
        gt = ctx.gene_type
        if gt is not None and 0 <= gt < len(ctx.types) and ctx.types[gt] is not None and ctx.left[gt] > 0:
            if all(a[1] != gt for a in new_actions):
                new_actions.append(("new", gt))

    return [("reuse", r) for r in reuses] + new_actions
```

The rule makes the no-deviation choice maintenance-urgent: it sends the available robot closest to its work-budget limit (lowest duties-left/budget, with short away-time and longest-ready as tie-breakers) so maintenance is started early and cycles stay staggered, preserving fresher robots as reserve. The remaining reuse options stay in the decoder’s balanced default order, letting sparse deviations switch to round-robin balancing; new-robot fallbacks respect the genome’s type first, then prefer horizon-fitting types.

```python
def rule(ctx):
    avail = list(ctx.available)
    actions = []

    if avail:
        best = None
        best_key = None
        for r in avail:
            ti = ctx.types[r.type] or {}
            wt = ti.get("work_time", 10)
            out = ti.get("out_travel_time", 0)
            ret = ti.get("return_travel_time", 0)
            charge = ti.get("charge_time", 0)
            maint = ti.get("maintenance_time", 0)
            away = out + wt + ret + (maint if r.duties_left <= 1 else charge)
            key = (r.duties_left, r.budget, away, r.count, r.hours, r.ready, r.idx)
            if best_key is None or key < best_key:
                best_key = key
                best = r

        actions.append(("reuse", best))
        for r in avail:
            if r.idx != best.idx:
                actions.append(("reuse", r))

    types = []
    gt = ctx.gene_type
    if 0 <= gt < len(ctx.types) and ctx.types[gt] is not None and ctx.left[gt] > 0:
        types.append(gt)

    rem = ctx.remaining
    other = []
    for k, ti in enumerate(ctx.types):
        if ti is None or ctx.left[k] <= 0:
            continue
        if k == gt and k in types:
            continue
        wt = ti.get("work_time", 10)
        if rem > 0:
            if wt <= rem:
                key = (0, -wt, k)
            else:
                key = (1, wt - rem, k)
        else:
            key = (2, wt, k)
        other.append((key, k))
    other.sort()
    for _, k in other:
        types.append(k)

    if not types:
        types.append(gt)

    for k in types:
        actions.append(("new", k))

    return actions
```

The rule uses look-ahead to keep the roster resource-efficient: during most of the horizon it prefers the available robot closest to its maintenance limit, which staggers maintenance and keeps fresh robots as backup; only when capacity is clearly insufficient or all available robots are about to enter maintenance does it open a new robot early. Near the end it switches to a combined count/hour load-balancing key so final duty counts and duty hours become more even. New robot types are ordered by how well their duty length fits the remaining horizon and by cycle efficiency (maintenance/charge/travel).

```python
def rule(ctx):
    types = ctx.types
    ntypes = len(types)
    valid_new = [k for k in range(ntypes) if types[k] is not None and ctx.left[k] > 0]

    wts = [types[k]['work_time'] for k in range(ntypes) if types[k] is not None]
    if wts:
        avg_wt = sum(wts) / len(wts)
        max_wt = max(wts)
    else:
        avg_wt = 10.0
        max_wt = 10.0

    remaining = max(0.0, ctx.remaining)

    def type_key(k):
        tp = types[k]
        wt = tp['work_time']
        cmw = tp.get('continue_max_work', 0.0)
        ct = tp.get('charge_time', 0.0)
        mt = tp.get('maintenance_time', 0.0)
        tr = tp.get('out_travel_time', 0.0) + tp.get('return_travel_time', 0.0)
        if wt <= remaining:
            return (0, -wt, -cmw, ct, mt, tr, k)
        else:
            return (1, wt, -cmw, ct, mt, tr, k)

    sorted_new = sorted(valid_new, key=type_key)
    new_actions = [("new", k) for k in sorted_new]

    av = list(ctx.available)
    if not av:
        return new_actions if new_actions else [("new", ctx.gene_type)]

    near_end = remaining < 6.0 * avg_wt

    if near_end:
        def reuse_key(r):
            load = r.count + r.hours / max(1.0, avg_wt)
            return (load, r.duties_left, r.idx)
    else:
        def reuse_key(r):
            load = r.count + r.hours / max(1.0, avg_wt)
            return (r.duties_left, load, r.idx)

    sorted_av = sorted(av, key=reuse_key)
    reuse_actions = [("reuse", r) for r in sorted_av]

    open_early = False
    if ctx.capacity < remaining:
        shortfall = remaining - ctx.capacity
        near_maint = all(r.duties_left <= 1 for r in av)
        if shortfall > max_wt or near_maint:
            open_early = True

    if open_early and new_actions:
        return new_actions + reuse_actions
    return reuse_actions + new_actions
```

The rule keeps Rule 2’s maintenance-urgency logic for the early/middle horizon, but near the end it switches to a load-balancing policy that also avoids sending a robot into maintenance unless it can return and work again before the horizon. Alternatives are ordered complementarily, and new-robot types are ranked by horizon fit/capacity with the gene type as a tie-breaker.

```python
def rule(ctx):
    avail = list(ctx.available)

    max_maint = 0
    max_cyc = 0
    for ti in ctx.types:
        if ti is None:
            continue
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        cyc = out + wt + ret + ch
        if mt > max_maint:
            max_maint = mt
        if cyc > max_cyc:
            max_cyc = cyc

    late = ctx.remaining <= (max_maint + 2 * max_cyc)

    def rparams(r):
        ti = ctx.types[r.type] or {}
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        return wt, out, ret, ch, mt

    def urgency_key(r):
        wt, out, ret, ch, mt = rparams(r)
        away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
        bad = 0
        if r.duties_left <= 1 and (out + wt + ret + mt > ctx.remaining):
            bad = 1
        return (bad, r.duties_left, r.budget, away, r.count, r.hours, r.ready, r.idx)

    def balance_key(r):
        wt, out, ret, ch, mt = rparams(r)
        away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
        bad = 0
        if r.duties_left <= 1 and (out + wt + ret + mt > ctx.remaining):
            bad = 1
        return (bad, r.count, r.hours, -r.duties_left, -r.budget, away, r.ready, r.idx)

    def late_key(r):
        wt, out, ret, ch, mt = rparams(r)
        if r.duties_left <= 1:
            useful = (out + wt + ret + mt + out + wt + ret <= ctx.remaining)
            if useful:
                urg = 0
            else:
                urg = 2
        else:
            urg = 1
        away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
        return (urg, r.count, r.hours, -r.duties_left, -r.budget, away, r.ready, r.idx)

    actions = []
    if avail:
        if late:
            ordered = sorted(avail, key=late_key)
            for r in ordered:
                actions.append(("reuse", r))
        else:
            ordered = sorted(avail, key=urgency_key)
            actions.append(("reuse", ordered[0]))
            for r in sorted(ordered[1:], key=balance_key):
                actions.append(("reuse", r))

    rem = ctx.remaining
    gt = ctx.gene_type
    valid = []
    for k, ti in enumerate(ctx.types):
        if ti is None or ctx.left[k] <= 0:
            continue
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        cont = ti.get("continue_max_work", 0) or 0

        if rem <= 0:
            fit = (0, 0)
        elif wt <= rem:
            fit = (0, -wt)
        else:
            fit = (1, wt - rem)

        cap = (-cont, mt, ch, out + ret, -wt, k)
        gene_pen = 0 if k == gt else 1
        valid.append((fit, gene_pen, cap, k))

    valid.sort()
    for item in valid:
        actions.append(("new", item[3]))

    if not valid:
        if isinstance(gt, int) and 0 <= gt < len(ctx.types) and ctx.types[gt] is not None:
            actions.append(("new", gt))
        else:
            fallback = None
            for k, ti in enumerate(ctx.types):
                if ti is not None and ctx.left[k] > 0:
                    fallback = k
                    break
            if fallback is None:
                fallback = gt
            actions.append(("new", fallback))

    return actions
```

The core weakness is group M (mixed 6/8/10/12 h duties): the old rule ranks reuse candidates by `duties_left`, which is a count of duties and is *not* comparable across robot types with different `single_work_time`. I switch the primary selection to remaining `budget` (work-hours left before maintenance), which is type-agnostic and still implements the "drain the robot closest to maintenance" policy that keeps maintenance events staggered (avoiding simultaneous absences and thus extra robots). I keep the feasibility-aware "away" time as the second key, now explicitly adding maintenance time when the duty would trigger maintenance (so a long absence is penalised), then use count/hours for balance as late tiebreaks. This barely changes E/H (single duty length, so budget ∝ duties_left) but fixes cross-type ordering in M. The no-deviation path stays resource-lean, while the remaining reuse alternatives are left in the decoder's default `(count asc, budget desc)` order so random deviations can explore more balanced assignments, and the "new type" ordering is unchanged (prefer gene type, then largest duty that fits the remaining horizon).

```python
def rule(ctx):
    avail = list(ctx.available)
