            if r.duties_left <= 1:
                away = out + wt + ret + maint
            else:
                away = out + wt + ret + charge
            key = (r.budget, away, r.count, r.hours, r.ready, r.idx)
            if best_key is None or key < best_key:
                best_key = key
                best = r

        actions.append(("reuse", best))
        for r in avail:
            if r.idx != best.idx:
                actions.append(("reuse", r))

