        types.append(gt)

    rem = ctx.remaining
    other = []
    for k, ti in enumerate(ctx.types):
        if ti is None or ctx.left[k] <= 0:
            continue
        if k in types:
            continue
        wt = ti.get("work_time", 10)
        if rem > 0:
            if wt <= rem:
                key = (0, -wt, k)
