The main change targets the mixed-duty M group: for mixed work times the rule now favors balanced duty counts (then hours) among available robots instead of always using the lowest remaining budget, which can over-concentrate work across different duty lengths. Uniform E/H groups keep the original budget-first tie-breaking, which staggers maintenance well there. For opening new robots on mixed horizons, I also add a small remainder-coverability check so the rule avoids leaving a 2/4h dead-end, prefers larger fitting duties near the horizon end, and otherwise uses the existing efficiency heuristic.

```python
def rule(ctx):
    avail = list(ctx.available)
    actions = []

    # Detect whether the instance has mixed duty lengths.
    wts = []
    for ti in ctx.types:
        if ti is not None:
            wt = ti.get("work_time", 10)
            if wt not in wts:
                wts.append(wt)
    mixed = len(wts) > 1

    def away_of(r):
        ti = ctx.types[r.type] or {}
        wt = ti.get("work_time", 10)
        out = ti.get("out_travel_time", 0)
        ret = ti.get("return_travel_time", 0)
        charge = ti.get("charge_time", 0)
        maint = ti.get("maintenance_time", 0)
        return out + wt + ret + (maint if r.duties_left <= 1 else charge)

    def base_key(r):
        return (r.budget, away_of(r), r.count, r.hours,
                r.duties_left, r.ready, r.idx)

    def mixed_key(r):
        # For mixed duty lengths, balance counts first, then hours,
        # and only then use remaining budget/urgency.
        return (r.count, r.hours, r.budget, away_of(r),
                r.duties_left, r.ready, r.idx)

    if avail:
        if mixed:
            best = min(avail, key=mixed_key)
            others = [r for r in avail if r.idx != best.idx]
            others.sort(key=mixed_key)
        else:
            best = min(avail, key=base_key)
            others = [r for r in avail if r.idx != best.idx]

        actions.append(("reuse", best))
        for r in others:
            actions.append(("reuse", r))

    rem = ctx.remaining

    opened = set()
    for r in ctx.robots:
        if 0 <= r.type < len(ctx.types):
            opened.add(r.type)

    poss_wts = []
    for k, ti in enumerate(ctx.types):
        if ti is not None and ctx.left[k] > 0:
            wt = ti.get("work_time", 10)
            if wt > 0 and wt not in poss_wts:
                poss_wts.append(wt)

    # Small subset-sum for short leftover remainders.
    maxc = 30
    cover = [False] * (maxc + 1)
    cover[0] = True
    for s in range(1, maxc + 1):
        for w in poss_wts:
            if s >= w and cover[s - w]:
                cover[s] = True
                break

    def coverable(x):
        if x == 0:
            return True
        if x < 0:
            return False
        if x <= maxc:
            return cover[x]
        return True

    max_wt = max(poss_wts) if poss_wts else 0
    mixed_possible = len(set(poss_wts)) > 1

    type_candidates = []
    for k, ti in enumerate(ctx.types):
        if ti is None or ctx.left[k] <= 0:
            continue

        wt = ti.get("work_time", 10)
        single = ti.get("single_work_time", wt)
        if single <= 0:
            single = wt if wt > 0 else 1
        cmw = ti.get("continue_max_work", single)
        out = ti.get("out_travel_time", 0)
        ret = ti.get("return_travel_time", 0)
        charge = ti.get("charge_time", 0)
        maint = ti.get("maintenance_time", 0)

        duties_per_maint = cmw / single if single > 0 else 1.0
        if duties_per_maint < 1.0:
            duties_per_maint = 1.0
        cycle = out + wt + ret + charge + maint / duties_per_maint
        eff = wt / cycle if cycle > 0 else 0.0

        fits = wt <= rem
        if fits:
            left_rem = rem - wt
            good_rem = coverable(left_rem)

            if not mixed_possible:
                # Preserve original E/H behavior.
                key = (0, 0, -eff, -wt, -ctx.left[k], k)
            else:
                is_open = 0 if k in opened else 1
                if rem < 3 * max_wt:
                    key = (0, 0 if good_rem else 1, -wt, is_open,
                           -eff, -ctx.left[k], k)
                else:
                    key = (0, 0 if good_rem else 1, -eff, is_open,
                           -wt, -ctx.left[k], k)
        else:
            over_pen = wt - rem
            if not mixed_possible:
                key = (1, over_pen, -eff, -wt, -ctx.left[k], k)
            else:
                is_open = 0 if k in opened else 1
                key = (1, over_pen, is_open, -eff, -wt,
                       -ctx.left[k], k)

        type_candidates.append((key, k))

    type_candidates.sort()
    for _, k in type_candidates:
        actions.append(("new", k))

    if not type_candidates:
        gt = ctx.gene_type
        if 0 <= gt < len(ctx.types) and ctx.types[gt] is not None:
            actions.append(("new", gt))
        elif len(ctx.types) > 0:
            actions.append(("new", 0))

    return actions
```

The rule uses a heterogeneity-adaptive strategy: for mixed duty-length instances it prioritizes maintenance timing and duty-fit so long maintenance cycles are started early and new types do not overshoot the remaining horizon; for homogeneous instances it uses a balance-first ordering with a maintenance-staggering window, which is better for even duty counts/hours and for making random reuse deviations useful. New-robot ordering is also adapted to whether duty lengths vary.

```python
def rule(ctx):
    work_times = []
    max_maint = 0
    max_cyc = 0
    for ti in ctx.types:
        if ti is None:
            continue
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        work_times.append(wt)
        if mt > max_maint:
            max_maint = mt
        cyc = out + wt + ret + ch
        if cyc > max_cyc:
            max_cyc = cyc

    if work_times:
        mixed = (max(work_times) - min(work_times)) > 0.1
    else:
        mixed = False

    avail = list(ctx.available)

    if mixed:
        def rparams(r):
            ti = ctx.types[r.type] or {}
            wt = ti.get("work_time", 10)
            if wt is None:
                wt = 10
            out = ti.get("out_travel_time", 0) or 0
            ret = ti.get("return_travel_time", 0) or 0
            ch = ti.get("charge_time", 0) or 0
            mt = ti.get("maintenance_time", 0) or 0
            return wt, out, ret, ch, mt

        late = ctx.remaining <= (max_maint + 2 * max_cyc)

        def urgency_key(r):
            wt, out, ret, ch, mt = rparams(r)
            away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
            bad = 0
            if r.duties_left <= 1 and (out + wt + ret + mt > ctx.remaining):
                bad = 1
            return (bad, r.duties_left, r.budget, away, r.count, r.hours, r.ready, r.idx)

        def balance_key(r):
            wt, out, ret, ch, mt = rparams(r)
            away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
            bad = 0
            if r.duties_left <= 1 and (out + wt + ret + mt > ctx.remaining):
                bad = 1
            return (bad, r.count, r.hours, -r.duties_left, -r.budget, away, r.ready, r.idx)

        def late_key(r):
            wt, out, ret, ch, mt = rparams(r)
            if r.duties_left <= 1:
                useful = (out + wt + ret + mt + out + wt + ret <= ctx.remaining)
                if useful:
                    urg = 0
                else:
                    urg = 2
            else:
                urg = 1
            away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
            return (urg, r.count, r.hours, -r.duties_left, -r.budget, away, r.ready, r.idx)

        actions = []
        if avail:
            if late:
                ordered = sorted(avail, key=late_key)
                for r in ordered:
                    actions.append(("reuse", r))
            else:
                ordered = sorted(avail, key=urgency_key)
                actions.append(("reuse", ordered[0]))
                for r in sorted(ordered[1:], key=balance_key):
                    actions.append(("reuse", r))

        rem = ctx.remaining
        gt = ctx.gene_type
        valid = []
        for k, ti in enumerate(ctx.types):
            if ti is None or ctx.left[k] <= 0:
                continue
            wt = ti.get("work_time", 10)
            if wt is None:
                wt = 10
            out = ti.get("out_travel_time", 0) or 0
            ret = ti.get("return_travel_time", 0) or 0
            ch = ti.get("charge_time", 0) or 0
            mt = ti.get("maintenance_time", 0) or 0
            cont = ti.get("continue_max_work", 0) or 0

            if rem <= 0:
                fit = (0, 0)
            elif wt <= rem:
                fit = (0, -wt)
            else:
                fit = (1, wt - rem)

            cap = (-cont, mt, ch, out + ret, -wt, k)
            valid.append((fit, cap, k))

        valid.sort()
        for item in valid:
            actions.append(("new", item[2]))

        if not valid:
            if isinstance(gt, int) and 0 <= gt < len(ctx.types) and ctx.types[gt] is not None:
                actions.append(("new", gt))
            else:
                fallback = None
                for k, ti in enumerate(ctx.types):
                    if ti is not None and ctx.left[k] > 0:
                        fallback = k
                        break
                if fallback is None:
                    fallback = gt
                actions.append(("new", fallback))

        return actions

    else:
        def new_score(tr):
            cont = tr.get("continue_max_work", 1.0)
            work = tr.get("work_time", 1.0)
            single = tr.get("single_work_time", work)
            maint = tr.get("maintenance_time", 1.0)
            charge = tr.get("charge_time", 1.0)
            cap = cont * work / max(1e-6, single)
            return maint / max(1.0, cap) + charge / max(1.0, work) - work / 10.0

        if not avail:
            cand = []
            for k in range(len(ctx.types)):
                tr = ctx.types[k]
                if tr is not None and ctx.left[k] > 0:
                    cand.append((new_score(tr), k))
            cand.sort()
            actions = [("new", k) for _, k in cand]
            if not actions:
                actions = [("new", ctx.gene_type)]
            return actions

        total_count = 0
        total_hours = 0.0
        for r in ctx.robots:
            total_count += r.count
            total_hours += r.hours
        avg_work = total_hours / total_count if total_count > 0 else 10.0
        if avg_work <= 0.0:
            avg_work = 10.0

        info = []
        for r in avail:
            tr = ctx.types[r.type] if r.type < len(ctx.types) else None
            if tr is not None:
                single = tr.get("single_work_time", tr.get("work_time", 1.0))
                cont = tr.get("continue_max_work", 1.0)
                max_duties = cont / single if single > 0 else 1.0
                if max_duties < 1.0:
                    max_duties = 1.0
            else:
                max_duties = max(1.0, float(r.duties_left))

            rem_frac = r.duties_left / max_duties
            load = 0.5 * (r.count + r.hours / avg_work)
            info.append((rem_frac, load, r.idx, r))

        window = 0.5
        in_window = [x for x in info if x[0] <= window]
        if in_window:
            in_window.sort(key=lambda x: (x[0], x[1], x[2]))
            rest = [x for x in info if x[0] > window]
            rest.sort(key=lambda x: (x[1], x[2]))
            ordered = in_window + rest
        else:
            info.sort(key=lambda x: (x[1], x[2]))
            ordered = info

        actions = [("reuse", x[3]) for x in ordered]

        cand = []
        for k in range(len(ctx.types)):
            tr = ctx.types[k]
            if tr is not None and ctx.left[k] > 0:
                cand.append((new_score(tr), k))
        cand.sort()
        actions.extend(("new", k) for _, k in cand)
        if not cand:
            actions.append(("new", ctx.gene_type))
        return actions
