The combined rule keeps the maintenance-cycle focus that made Rule 1 strong—draining robots that are close to maintenance to stagger downtime—but improves it by excluding duty time from the readiness penalty and by switching to an endgame balancing strategy when the remaining horizon is shorter than the longest maintenance interval. In that final phase it avoids triggering maintenance that cannot finish before the horizon, and it prioritizes balancing duty counts/hours first. The alternative reuse list still follows the decoder’s balance-friendly default order, and new-type choices prefer a good horizon fit with shorter maintenance/charge overhead.

```python
def rule(ctx):
    avail = list(ctx.available)
    actions = []

    if avail:
        max_maint = 0
        for ti in ctx.types:
            if ti is not None:
                m = ti.get("maintenance_time", 0)
                if m > max_maint:
                    max_maint = m

        endgame = ctx.remaining <= max_maint

        best = None
        best_key = None
        for r in avail:
            ti = ctx.types[r.type] or {}
            wt = ti.get("work_time", 10)
            out = ti.get("out_travel_time", 0)
            ret = ti.get("return_travel_time", 0)
            charge = ti.get("charge_time", 0)
            maint = ti.get("maintenance_time", 0)

            will_maint = r.duties_left <= 1
            downtime = out + ret + (maint if will_maint else charge)
            risk = 0
            if will_maint and ctx.remaining <= maint:
                risk = 1000000

            if endgame:
                key = (risk, r.count, r.hours, -r.duties_left, -r.budget,
                       downtime, r.ready, r.idx)
            else:
                key = (r.duties_left, r.budget, downtime, r.count, r.hours,
                       -wt, r.ready, r.idx)

            if best_key is None or key < best_key:
                best_key = key
                best = r

        actions.append(("reuse", best))
        for r in avail:
            if r.idx != best.idx:
                actions.append(("reuse", r))

    types = []
    gt = ctx.gene_type
    if 0 <= gt < len(ctx.types) and ctx.types[gt] is not None and ctx.left[gt] > 0:
        types.append(gt)

    rem = ctx.remaining
    other = []
    for k, ti in enumerate(ctx.types):
        if ti is None or ctx.left[k] <= 0:
            continue
        if k in types:
            continue
        wt = ti.get("work_time", 10)
