        mt = ti.get("maintenance_time", 0) or 0
        cont = ti.get("continue_max_work", 0) or 0
        single = ti.get("single_work_time", wt) or wt
        if single <= 0:
            single = wt if wt > 0 else 1
        maxd = cont / single if cont > 0 else 1.0
        if maxd < 1.0:
            maxd = 1.0
        return wt, out, ret, ch, mt, maxd

    avail = list(ctx.available)
    nrob = len(ctx.robots)
    if nrob > 0:
        avg_count = sum(r.count for r in ctx.robots) / float(nrob)
        avg_hours = sum(r.hours for r in ctx.robots) / float(nrob)
    else:
        avg_count = 0.0
        avg_hours = 0.0

    total_cap = 0.0
    for r in ctx.robots:
        wt_r, _, _, _, _, _ = params(r)
        dl = r.duties_left
        if dl is None:
            dl = 1
        if dl < 0:
            dl = 0
        total_cap += dl * wt_r

    scored = []
    for r in avail:
        wt, out, ret, ch, mt, maxd = params(r)
        dl = r.duties_left
        if dl is None:
            dl = 1
        rem_frac = dl / maxd if maxd > 0 else 1.0
        if rem_frac > 1.0:
            rem_frac = 1.0

        load = (r.count - avg_count) / max(1.0, abs(avg_count) + 1.0)
        load += (r.hours - avg_hours) / max(1.0, abs(avg_hours) + 1.0)

        future_t = ctx.t + wt
        future_avail = 0
        for q in ctx.robots:
            if q.idx != r.idx and q.ready <= future_t:
                future_avail += 1

        if future_avail <= 0:
            gap_pen = 50.0
        elif future_avail == 1:
            gap_pen = 2.0
        else:
            gap_pen = 0.0

        will_maint = dl <= 1
        maint_pen = 0.0
        if will_maint:
            own_cap = dl * wt
            other_cap = total_cap - own_cap
            if other_cap < mt:
                maint_pen = 10.0 * (mt - other_cap) / max(1.0, mt)
            else:
                maint_pen = -1.0

        ratio = mt / max(1.0, wt * maxd)
        thr = 0.5 + 0.08 * (ratio - 1.0)
        if thr < 0.4:
            thr = 0.4
        if thr > 0.65:
            thr = 0.65

        urg = 0.0
        if rem_frac < thr:
            urg = (thr - rem_frac) / thr

        score = 2.0 * load + gap_pen + maint_pen - 3.0 * urg
        scored.append((score, r.idx, r))

    scored.sort(key=lambda x: (x[0], x[1]))
    actions = [("reuse", item[2]) for item in scored]

    new_cands = []
    for k, ti in enumerate(ctx.types):
        if ti is None or ctx.left[k] <= 0:
            continue
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        cont = ti.get("continue_max_work", 0) or 0
        single = ti.get("single_work_time", wt) or wt
        if single <= 0:
            single = wt if wt > 0 else 1
        maxd = cont / single if cont > 0 else 1.0
        if maxd < 1.0:
            maxd = 1.0
        cap = maxd * wt
        rem = ctx.remaining

        if wt <= rem:
            fit_pen = 0.0
        else:
            fit_pen = 10.0 * (wt - rem) / max(1.0, wt)

        overhead = (out + ret + ch) / max(1.0, wt)
        maint_cost = mt / max(1.0, cap)
        score = fit_pen + maint_cost + overhead - wt / 20.0
        new_cands.append((score, k))

    new_cands.sort(key=lambda x: (x[0], x[1]))
    for _, k in new_cands:
        actions.append(("new", k))

