        if not isinstance(gt, int) or gt < 0 or gt >= len(ctx.types) or ctx.types[gt] is None:
            gt = 0
            for k, ti in enumerate(ctx.types):
                if ti is not None:
                    gt = k
                    break
        actions.append(("new", gt))

    return actions
