The key improvement is to unify the mixed and non-mixed branches and replace the mixed branch’s pure maintenance urgency with a load-balanced, bucketed urgency rule. Robots are normally balanced by duty count and normalized hours, but once a robot enters a maintenance-critical window, it gets priority; the window and bucket width adapt to the remaining capacity slack so tight instances keep the original stagger, while slack-rich instances allow more balancing. Near the horizon, fitting duty lengths are preferred, and new-robot types are ordered by a resource-cost estimate that includes travel, charging, maintenance, and budget.

```python
def rule(ctx):
    ntypes = len(ctx.types)
    params = []
    max_work = 0.0
    for k in range(ntypes):
        ti = ctx.types[k]
        if ti is None:
            params.append(None)
            continue
        work = ti.get("work_time", 10)
        if work is None:
            work = 10.0
        out = ti.get("out_travel_time", 0) or 0.0
        ret = ti.get("return_travel_time", 0) or 0.0
        charge = ti.get("charge_time", 0) or 0.0
        maint = ti.get("maintenance_time", 0) or 0.0
        cont = ti.get("continue_max_work", 1.0) or 1.0
        single = ti.get("single_work_time", work) or work
        max_duties = cont / single if single > 0 else 1.0
        if max_duties < 1.0:
            max_duties = 1.0
        denom = max(work, 1e-6)
        cost = (out + ret + charge) / denom + maint * single / max(1e-6, cont * work)
        params.append((work, out, ret, charge, maint, cont, single, max_duties, cost))
        if work > max_work:
            max_work = work

    total_count = 0
    total_hours = 0.0
    for r in ctx.robots:
        total_count += r.count
        total_hours += r.hours
    if total_count > 0:
        avg_work = total_hours / total_count
    else:
        ws = [p[0] for p in params if p is not None]
        avg_work = sum(ws) / len(ws) if ws else 10.0
    if avg_work <= 0:
        avg_work = 10.0

    if ctx.remaining > 0:
        slack = ctx.capacity / ctx.remaining
    else:
        slack = 1.0

    if slack > 1.5:
        window = 0.25
        step = 0.20
    elif slack > 1.2:
        window = 0.35
        step = 0.12
    else:
        window = 0.5
        step = 0.06

    def new_key(k):
        p = params[k]
        work = p[0]
        cost = p[8]
        if ctx.remaining < max_work:
            if work <= ctx.remaining:
                fit_key = (0, -work)
            else:
                fit_key = (1, work - ctx.remaining)
        else:
            fit_key = (0, 0.0)
        return (fit_key, cost, k)

    avail = list(ctx.available)
    if not avail:
        cand = []
        for k, p in enumerate(params):
            if p is not None and ctx.left[k] > 0:
                cand.append(new_key(k))
        cand.sort()
        actions = [("new", item[2]) for item in cand]
        if not actions:
            gt = ctx.gene_type
            if isinstance(gt, int) and 0 <= gt < ntypes and ctx.types[gt] is not None:
                actions = [("new", gt)]
            else:
                fallback = None
                for k, ti in enumerate(ctx.types):
                    if ti is not None and ctx.left[k] > 0:
                        fallback = k
                        break
                if fallback is None:
                    fallback = gt
                actions = [("new", fallback)]
        return actions

    scored = []
    for r in avail:
        p = params[r.type] if r.type < len(params) else None
        if p is None:
            work = 10.0
            out = ret = charge = maint = 0.0
            cont = 1.0
            single = 10.0
            max_duties = 1.0
        else:
            work, out, ret, charge, maint, cont, single, max_duties, cost = p

        rem_frac = r.duties_left / max_duties if max_duties > 0 else 0.0
        if rem_frac > 1.0:
            rem_frac = 1.0
        elif rem_frac < 0.0:
            rem_frac = 0.0

        load = r.count + r.hours / avg_work

        hard_bad = 0
        fit_pen = 0.0
        if ctx.remaining < max_work:
            if work > ctx.remaining:
                hard_bad = 1
                fit_pen = 100.0 + (work - ctx.remaining)
            else:
                fit_pen = (ctx.remaining - work) * 0.1

        maint_pen = 0.0
        if r.duties_left <= 1 and ctx.remaining > work:
            if (out + work + ret + maint) > ctx.remaining:
                maint_pen = 1.0

        score = load + maint_pen
        if hard_bad:
            key = (2, fit_pen, score, rem_frac, r.idx)
        elif rem_frac <= window:
            bucket = int(rem_frac / step) if step > 0 else 0
            key = (0, bucket, score + fit_pen, rem_frac, r.idx)
        else:
            key = (1, score + fit_pen, rem_frac, r.idx)
        scored.append((key, r))

    scored.sort(key=lambda x: x[0])
    actions = [("reuse", r) for _, r in scored]

    cand = []
    for k, p in enumerate(params):
        if p is not None and ctx.left[k] > 0:
            cand.append(new_key(k))
    cand.sort()
    actions.extend(("new", item[2]) for item in cand)
    if not cand:
        actions.append(("new", ctx.gene_type))
    return actions
