The rule uses capacity-fed maintenance-concurrency control: when the opened fleet is short of remaining work it serializes maintenance by pushing one robot at a time toward its maintenance cycle, and it avoids starting a second maintenance while another robot is already down for maintenance; when capacity is sufficient it switches to load-balancing to reduce imbalance. New robot types are ranked by their effective work throughput per maintenance cycle and fit to the remaining horizon, rather than by raw budget/count keys.

```python
def rule(ctx):
    ntypes = len(ctx.types)

    def tparams(k):
        ti = ctx.types[k] if 0 <= k < ntypes else None
        if ti is None:
            ti = {}
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        cont = ti.get("continue_max_work", 0) or 0
        single = ti.get("single_work_time", wt)
        if single is None or single <= 0:
            single = wt if wt and wt > 0 else 1
        return wt, out, ret, ch, mt, cont, single

    def rparams(r):
        ti = ctx.types[r.type] if 0 <= r.type < ntypes else None
        if ti is None:
            ti = {}
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        cont = ti.get("continue_max_work", 0) or 0
        single = ti.get("single_work_time", wt)
        if single is None or single <= 0:
            single = wt if wt and wt > 0 else 1
        maxd = cont / single if cont > 0 else max(1.0, float(r.duties_left))
        if maxd < 1.0:
            maxd = 1.0
        return wt, out, ret, ch, mt, single, maxd

    rem = ctx.remaining
    tnow = ctx.t

    max_maint = 0
    max_cycle = 0
    for k, ti in enumerate(ctx.types):
        if ti is None:
            continue
        wt, out, ret, ch, mt, cont, single = tparams(k)
        cyc = out + wt + ret + ch
        if cyc > max_cycle:
            max_cycle = cyc
        if mt > max_maint:
            max_maint = mt

    late = rem <= (max_maint + 2 * max_cycle)

    maint_busy = 0
    for r in ctx.robots:
        if r.ready > tnow + 1e-9:
            wt, out, ret, ch, mt, single, maxd = rparams(r)
            if r.ready - tnow > ch + 0.5:
                maint_busy += 1

    cap = ctx.capacity
    tight = cap < rem - 1e-9

    def late_key(r):
        wt, out, ret, ch, mt, single, maxd = rparams(r)
        if r.duties_left <= 1:
            useful = (out + wt + ret + mt + out + wt + ret <= rem)
            urg = 0 if useful else 2
        else:
            urg = 1
        away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
        return (urg, r.count, r.hours, -r.duties_left, -r.budget,
                away, r.ready, r.idx)

    def tight_key(r):
        wt, out, ret, ch, mt, single, maxd = rparams(r)
        away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
        if maint_busy > 0:
            trigger = 0 if r.duties_left > 1 else 1
        else:
            trigger = 0 if r.duties_left <= 1 else 1
        return (trigger, r.duties_left, r.count, r.hours, -r.budget,
                away, r.ready, r.idx)

    def balance_key(r):
        wt, out, ret, ch, mt, single, maxd = rparams(r)
        away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
        guard = 0
        if maint_busy > 0 and r.duties_left <= 1:
            guard = 1
        return (guard, r.count, r.hours, -r.duties_left, -r.budget,
                away, r.ready, r.idx)

    avail = list(ctx.available)
    actions = []
    if avail:
        if late:
            ordered = sorted(avail, key=late_key)
        elif tight:
            ordered = sorted(avail, key=tight_key)
        else:
            ordered = sorted(avail, key=balance_key)
        actions = [("reuse", r) for r in ordered]

    valid = []
    for k, ti in enumerate(ctx.types):
        if ti is None or ctx.left[k] <= 0:
            continue
        wt, out, ret, ch, mt, cont, single = tparams(k)
        maxd = cont / single if cont > 0 else 1.0
        if maxd < 1.0:
            maxd = 1.0

        if rem <= 0:
            fit = 0
        elif wt <= rem:
            fit = 0
        else:
            fit = 1

        cycle_time = maxd * (out + wt + ret + ch) + mt
        coverage = maxd * wt
        eff = coverage / max(1.0, cycle_time)

        key = (fit, -eff, mt, ch, out + ret, -wt, -maxd, k)
        valid.append((key, k))

    valid.sort()
    for item in valid:
        actions.append(("new", item[1]))

    if not valid:
        if isinstance(ctx.gene_type, int) and 0 <= ctx.gene_type < ntypes and ctx.types[ctx.gene_type] is not None:
            actions.append(("new", ctx.gene_type))
        else:
            fallback = None
            for k, ti in enumerate(ctx.types):
                if ti is not None and ctx.left[k] > 0:
                    fallback = k
                    break
            if fallback is None:
                fallback = ctx.gene_type
            actions.append(("new", fallback))

    return actions
```

The rule keeps the decoder’s resource-saving bias by starting maintenance early when capacity is tight, but uses remaining work budget (hours) rather than duty count for urgency, which is important for the mixed 6/8/10/12 h group. When capacity has enough slack it switches to count/hour balancing, and in endgame it penalizes shifts that overrun the horizon or leave an uncoverable remainder. The ordered alternatives deliberately put the opposite trade-off first (balanced vs. urgent robot), and new-robot types are ranked by horizon fit before the genome’s gene type, making default openings robust while still exposing useful deviation choices.

```python
def rule(ctx):
    types = ctx.types
    rem = ctx.remaining
    avail = list(ctx.available)
    actions = []

    usable = []
    for k, ti in enumerate(types):
        if ti is not None and ctx.left[k] > 0:
            usable.append(k)
    for r in ctx.robots:
        found = False
        for k in usable:
            if k == r.type:
                found = True
                break
        if not found:
            usable.append(r.type)

    max_maint = 0
    max_work = 0
    min_work = 10**9
    for k in usable:
        ti = types[k] if 0 <= k < len(types) else None
        if ti is None:
            continue
        m = ti.get("maintenance_time", 0)
        if m > max_maint:
            max_maint = m
        wt = ti.get("work_time", 10)
        if wt > max_work:
            max_work = wt
        if wt < min_work:
            min_work = wt
    if min_work == 10**9:
        min_work = 10
    if max_work == 0:
        max_work = 10

    tight = ctx.capacity < rem + max_maint
    endgame = rem <= max_work

    best = None
    best_key = None
    best_bal = None
    best_bal_key = None
    best_urg = None
    best_urg_key = None

    for r in avail:
        ti = types[r.type] or {}
        wt = ti.get("work_time", 10)
        out = ti.get("out_travel_time", 0)
        ret = ti.get("return_travel_time", 0)
        charge = ti.get("charge_time", 0)
        maint = ti.get("maintenance_time", 0)
        single = ti.get("single_work_time", wt)

        will_maint = (r.duties_left <= 1) or (r.budget <= single)
        downtime = out + ret + (maint if will_maint else charge)

        risk = 0
        if will_maint and rem <= maint + out + ret + charge:
            risk = 1000000

        overrun = wt - rem if wt > rem else 0
        gap = 0
        if rem > wt and rem - wt > 0 and rem - wt < min_work:
            gap = 1

        bal_key = (overrun, gap, risk, r.count, r.hours,
                   -r.budget, -r.duties_left, downtime, -wt,
                   r.ready, r.idx)
        if best_bal_key is None or bal_key < best_bal_key:
            best_bal_key = bal_key
            best_bal = r

        urg_key = (overrun, gap, risk, r.budget, r.duties_left,
                   downtime, r.count, r.hours, -wt, r.ready, r.idx)
        if best_urg_key is None or urg_key < best_urg_key:
            best_urg_key = urg_key
            best_urg = r

        if endgame:
            key = (overrun, gap, risk, r.count, r.hours, -wt,
                   -r.budget, -r.duties_left, downtime, r.ready, r.idx)
        elif tight:
            key = urg_key
        else:
            key = bal_key

        if best_key is None or key < best_key:
            best_key = key
            best = r

    if best is not None:
        actions.append(("reuse", best))
        used = {best.idx}
        ordered_alt = []

        if best_bal is not None and best_bal.idx not in used:
            ordered_alt.append(best_bal)
            used.add(best_bal.idx)
        if best_urg is not None and best_urg.idx not in used:
            ordered_alt.append(best_urg)
            used.add(best_urg.idx)

        for r in avail:
            if r.idx not in used:
                ordered_alt.append(r)
                used.add(r.idx)

        for r in ordered_alt:
            actions.append(("reuse", r))

    new_candidates = []
    for k, ti in enumerate(types):
        if ti is None or ctx.left[k] <= 0:
            continue
        wt = ti.get("work_time", 10)
        out = ti.get("out_travel_time", 0)
        ret = ti.get("return_travel_time", 0)
        charge = ti.get("charge_time", 0)
        maint = ti.get("maintenance_time", 0)
        down = out + ret + charge + maint

        overrun = wt - rem if wt > rem else 0
        gap = 0
        if rem > wt and rem - wt > 0 and rem - wt < min_work:
            gap = 1

        if wt <= rem:
            key = (overrun, gap, 0, -wt, down, k)
        else:
            key = (overrun, gap, 1, wt, down, k)
        new_candidates.append((key, k))

    new_candidates.sort()
    ordered_new = []
    if new_candidates:
        ordered_new.append(new_candidates[0][1])

    gt = ctx.gene_type
    if 0 <= gt < len(types) and types[gt] is not None and ctx.left[gt] > 0:
        if gt not in ordered_new:
            ordered_new.append(gt)

    for _, k in new_candidates:
        if k not in ordered_new:
            ordered_new.append(k)

    if not ordered_new:
        if 0 <= gt < len(types) and types[gt] is not None:
            ordered_new.append(gt)

    for k in ordered_new:
        actions.append(("new", k))

    return actions
```

The rule always reuses an available robot, sorting candidates by a workload measure that combines duty count and duty hours normalized by the average duty length, while penalizing robots whose duty period would overshoot the remaining horizon. Ties favor robots with more remaining budget and earlier opening order. Only when no robot is available does it propose new robot types, preferring types that fit the remaining horizon and have a high duty-throughput rate with low maintenance overhead.

```python
def rule(ctx):
    types = ctx.types
    rem = ctx.remaining
    work_times = [p['work_time'] for p in types if p is not None]
    avg_w = sum(work_times) / len(work_times) if work_times else 10.0
    if avg_w <= 0:
        avg_w = 1.0

    def reuse_key(r):
        p = types[r.type]
        d = p['work_time']
        fit = 0.0
        if d > rem:
            fit = 1000.0 + (d - rem)
        load = r.count + r.hours / avg_w
        return (fit, load, r.count, r.hours, -r.duties_left, r.idx)

    actions = []
    avail = ctx.available
    if avail:
        for r in sorted(avail, key=reuse_key):
            actions.append(("reuse", r))
        return actions

    def new_key(k):
        p = types[k]
        d = p['work_time']
        fit = 0.0
        if d > rem:
            fit = 1000.0 + (d - rem)
        sw = p['single_work_time']
        cm = p['continue_max_work']
        if sw <= 0:
            sw = d if d > 0 else 1.0
        if cm <= 0:
            cm = 1.0
        cycle = p['out_travel_time'] + d + p['return_travel_time'] + p['charge_time']
        maint = p['maintenance_time']
        denom = cycle + (sw / cm) * maint
        rate = d / denom if denom > 0 else 0.0
        return (fit, -rate, maint, cycle, d, k)

    new_types = [k for k in range(len(types)) if types[k] is not None and ctx.left[k] > 0]
    if not new_types:
        if ctx.gene_type is not None:
            return [("new", ctx.gene_type)]
        return []
