```python
def rule(ctx):
    def type_params(ti):
        if ti is None:
            ti = {}
        wt = ti.get("work_time", 10)
        if wt is None:
            wt = 10
        out = ti.get("out_travel_time", 0) or 0
        ret = ti.get("return_travel_time", 0) or 0
        ch = ti.get("charge_time", 0) or 0
        mt = ti.get("maintenance_time", 0) or 0
        single = ti.get("single_work_time", wt)
        if single is None or single <= 0:
            single = wt if wt > 0 else 1
        cont = ti.get("continue_max_work", 0) or 0
        if cont <= 0:
            cont = single
        return wt, out, ret, ch, mt, single, cont

    def rparams(r):
        ti = ctx.types[r.type] if r.type < len(ctx.types) else None
        return type_params(ti)

    def late_key(r):
        wt, out, ret, ch, mt, single, cont = rparams(r)
        if r.duties_left <= 1:
            useful = (out + wt + ret + mt + out + wt + ret <= ctx.remaining)
            urg = 0 if useful else 2
        else:
            urg = 1
        away = out + wt + ret + (mt if r.duties_left <= 1 else ch)
        return (urg, r.count, r.hours, -r.duties_left, -r.budget, away, r.ready, r.idx)

    avail = list(ctx.available)
    work_times = []
    max_maint = 0
    max_cyc = 0
    for ti in ctx.types:
        if ti is None:
            continue
        wt, out, ret, ch, mt, single, cont = type_params(ti)
        work_times.append(wt)
        if mt > max_maint:
            max_maint = mt
        cyc = out + wt + ret + ch
        if cyc > max_cyc:
            max_cyc = cyc
    mixed = bool(work_times) and (max(work_times) - min(work_times) > 0.1)
    late = ctx.remaining <= (max_maint + 2 * max_cyc)
    gt = ctx.gene_type

    def fallback_new():
        if isinstance(gt, int) and 0 <= gt < len(ctx.types) and ctx.types[gt] is not None and ctx.left[gt] > 0:
            return gt
        for k, ti in enumerate(ctx.types):
            if ti is not None and ctx.left[k] > 0:
                return k
        return gt

    def new_candidates():
        rem = ctx.remaining
        if mixed:
            valid = []
            for k, ti in enumerate(ctx.types):
                if ti is None or ctx.left[k] <= 0:
                    continue
                wt, out, ret, ch, mt, single, cont = type_params(ti)
                if rem <= 0:
                    fit = (0, 0)
                elif wt <= rem:
                    fit = (0, -wt)
                else:
                    fit = (1, wt - rem)
                cap = (-cont, mt, ch, out + ret, -wt, k)
                gene_pen = 0 if k == gt else 1
                valid.append((fit, gene_pen, cap, k))
            valid.sort()
            return [("new", item[3]) for item in valid]
        else:
            def new_score(tr):
                wt, out, ret, ch, mt, single, cont = type_params(tr)
                cap = cont * wt / max(1e-6, single)
                return mt / max(1.0, cap) + ch / max(1.0, wt) - wt / 10.0

            cand = []
            for k in range(len(ctx.types)):
                tr = ctx.types[k]
                if tr is not None and ctx.left[k] > 0:
                    cand.append((new_score(tr), k))
            cand.sort()
            return [("new", k) for _, k in cand]

    if not avail:
        actions = new_candidates()
        if not actions:
            actions = [("new", fallback_new())]
        return actions

    if late:
        actions = [("reuse", r) for r in sorted(avail, key=late_key)]
    else:
        total_count = 0
        total_hours = 0.0
        for r in ctx.robots:
            total_count += r.count
            total_hours += r.hours
        avg_work = total_hours / total_count if total_count > 0 else 10.0
        if avg_work <= 0.0:
            avg_work = 10.0

        info = []
        for r in avail:
            wt, out, ret, ch, mt, single, cont = rparams(r)
            max_duties = cont / single if single > 0 else 1.0
            if max_duties < 1.0:
                max_duties = 1.0
            rem_frac = r.duties_left / max_duties
            load = 0.5 * (r.count + r.hours / avg_work)
            info.append((rem_frac, load, r.idx, r))

        in_window = [x for x in info if x[0] <= 0.5]
        if in_window:
            in_window.sort(key=lambda x: (x[0], x[1], x[2]))
            default = in_window[0]
        else:
            info.sort(key=lambda x: (x[1], x[2]))
            default = info[0]

        default_idx = default[3].idx
        rest = [x for x in info if x[3].idx != default_idx]
        rest.sort(key=lambda x: (x[1], x[3].count, x[3].hours, x[0], x[2]))
        ordered = [default] + rest
        actions = [("reuse", x[3]) for x in ordered]

    new_acts = new_candidates()
    actions.extend(new_acts)
    if not new_acts:
        actions.append(("new", fallback_new()))
    return actions
