def rule(ctx):
    ntypes = len(ctx.types)

    def tinfo(k):
        if k is None or k < 0 or k >= ntypes:
            return None
        tr = ctx.types[k]
        if tr is None:
            return None
        wt = tr.get("work_time", 10)
        if wt is None or wt <= 0:
            wt = 10.0
        out = tr.get("out_travel_time", 0) or 0
        ret = tr.get("return_travel_time", 0) or 0
        ch = tr.get("charge_time", 0) or 0
        mt = tr.get("maintenance_time", 0) or 0
        single = tr.get("single_work_time", wt)
        if single is None or single <= 0:
            single = wt
        cont = tr.get("continue_max_work", 0) or 0
        return (wt, out, ret, ch, mt, single, cont)

    infos = [tinfo(k) for k in range(ntypes)]
    work_times = []
    max_cycle = 0.0

    for inf in infos:
        if inf is not None:
            wt, out, ret, ch, mt, single, cont = inf
            work_times.append(wt)
            cyc = out + wt + ret + ch
            if cyc > max_cycle:
                max_cycle = cyc

    if work_times:
        min_w = min(work_times)
        avg_type_w = sum(work_times) / len(work_times)
    else:
        min_w = 1.0
        avg_type_w = 10.0

    if min_w <= 0:
        min_w = 1.0

    g = 0
    for w in work_times:
        try:
            iw = int(round(w))
            if iw > 0:
                g = math.gcd(g, iw)
        except Exception:
            pass
    if g <= 0:
        g = 1

    robots = list(ctx.robots)
    N = len(robots)
    if N < 1:
        N = 1

    total_count = 0
    total_hours = 0.0
    for r in robots:
        total_count += r.count
        total_hours += r.hours

    avg_work = total_hours / total_count if total_count > 0 else avg_type_w
    if avg_work <= 1e-9:
        avg_work = avg_type_w if avg_type_w > 1e-9 else 10.0

    R = ctx.remaining
    target_count = (total_count + R / max(avg_work, 1e-9)) / N
    target_hours = (total_hours + R) / N

    try:
        cap_est = ctx.capacity
    except Exception:
        cap_est = R
    tight = cap_est < R + max_cycle + 1e-9

    avail = list(ctx.available)
    n_good = 0
    for r in avail:
        if r.duties_left > 1:
            n_good += 1

    def robot_score(r):
        inf = tinfo(r.type)
        if inf is None:
            wt, out, ret, ch, mt, single, cont = 10.0, 0.0, 0.0, 0.0, 0.0, 10.0, 0.0
        else:
            wt, out, ret, ch, mt, single, cont = inf

        dl = r.duties_left
        pred_count = r.count + 1
        pred_hours = r.hours + wt

        sc = (target_count - pred_count) + (target_hours - pred_hours) / max(avg_work, 1e-6)

        if R > 1e-9:
            if wt > R + 1e-9:
                sc -= 1000.0 + (wt - R)
            else:
                rem_after = R - wt
                if rem_after > 1e-9:
                    if rem_after < min_w - 1e-9:
                        sc -= 200.0 + (min_w - rem_after)
                    elif g > 1:
                        try:
                            if int(round(rem_after)) % g != 0:
                                sc -= 30.0
                        except Exception:
                            pass
                else:
                    sc += 1.0

        if dl <= 1:
            if R > wt + 1e-9:
                away = out + wt + ret + mt
                can_return = R > away + min_w - 1e-9
                if can_return:
                    if tight:
                        sc += 1.5
                    else:
                        sc += 0.25
                else:
                    if R - wt > min_w - 1e-9:
                        if n_good > 0:
                            sc -= 40.0 if tight else 12.0
                        else:
                            sc -= 1.0
            else:
                sc += 0.5
        else:
            sc += 0.002 * dl

        sc -= 1e-6 * r.idx
        return sc

    ordered = sorted(avail, key=robot_score, reverse=True)
    actions = [("reuse", r) for r in ordered]

    def new_score(k):
        inf = infos[k]
        if inf is None or ctx.left[k] <= 0:
            return (1e9, k)

        wt, out, ret, ch, mt, single, cont = inf
        fit = 0.0

        if R > 1e-9:
            if wt > R + 1e-9:
                fit += 1000.0 + (wt - R)
            else:
                rem_after = R - wt
                if rem_after > 1e-9:
                    if rem_after < min_w - 1e-9:
                        fit += 200.0 + (min_w - rem_after)
                    elif g > 1:
                        try:
                            if int(round(rem_after)) % g != 0:
                                fit += 30.0
                        except Exception:
                            pass
                else:
                    fit -= 1.0

        cap_duties = cont / single if single > 0 else 1.0
        if cap_duties < 1.0:
            cap_duties = 1.0

        eff = (
            mt / max(1.0, cap_duties * wt)
            + ch / max(1.0, wt)
            + (out + ret) / max(1.0, wt)
        )
        return (fit, eff, -cap_duties, mt, ch, out + ret, -wt, k)

    valid_new = []
    for k in range(ntypes):
        if infos[k] is not None and ctx.left[k] > 0:
            valid_new.append(k)
    valid_new.sort(key=new_score)

    for k in valid_new:
        actions.append(("new", k))

    if not valid_new:
        gt = ctx.gene_type
        if isinstance(gt, int) and 0 <= gt < ntypes and infos[gt] is not None:
            actions.append(("new", gt))
        else:
            fallback = None
            for k in range(ntypes):
                if infos[k] is not None:
                    fallback = k
                    break
            if fallback is not None:
                actions.append(("new", fallback))
            elif isinstance(gt, int):
                actions.append(("new", gt))

    if not actions:
        actions.append(("new", ctx.gene_type))

    return actions
